-- Наполнение БД VolleyReg тестовыми данными.
-- Выполняется в Adminer (раздел «SQL-запрос») или командой:
--   docker exec -i volleyreg-db psql -U volleyreg -d volleyreg < resources/db/seed.sql
-- Пароль всех пользователей: 123456 (bcrypt)

TRUNCATE team_application_participants, team_applications, participants, users RESTART IDENTITY;





SELECT setval('users_id_seq', (SELECT MAX(id) FROM users));
SELECT setval('participants_id_seq', (SELECT MAX(id) FROM participants));
SELECT setval('team_applications_id_seq', (SELECT MAX(id) FROM team_applications));
