INSERT INTO participants (id, full_name, description, is_deleted, image_key, video_key, birth_date, position, height_cm, sport_rank, city) VALUES
(1, 'Ковалёва Анна Сергеевна', 'Связующая с точной передачей в первый темп. Хорошо читает блок соперника и быстро разводит нападающих по зонам. Капитан студенческой сборной ЗГУ в сезоне 2025/26.', false, 'participant_1.jpg', 'video_1.mp4', '2004-03-14', 'Связующая', 176, 'КМС', 'Норильск'),
(2, 'Миронова Екатерина Олеговна', 'Доигровщица универсального плана: уверенный приём подачи и сильный удар из четвёртой зоны. Стабильно подаёт планирующую подачу в зону либеро соперника.', false, 'participant_2.jpg', 'video_2.mp4', '2003-07-02', 'Доигровщица', 181, '1 разряд', 'Норильск'),
(3, 'Белова Дарья Андреевна', 'Центральная блокирующая с высоким прыжком. Ставит групповой блок и атакует быстрым ударом с передачи в первый темп. Лучшая блокирующая краевого первенства 2025 года.', false, 'participant_3.jpg', 'video_3.mp4', '2005-01-23', 'Центральная блокирующая', 188, 'КМС', 'Красноярск'),
(4, 'Сафина Алина Ринатовна', 'Либеро, отвечает за приём подачи и игру в защите. Отличная реакция на сложных мячах, подстраховка блока и точная доводка мяча на связующую.', false, 'participant_4.jpg', 'video_1.mp4', '2004-11-09', 'Либеро', 165, '1 разряд', 'Норильск'),
(5, 'Громова Полина Игоревна', 'Диагональная нападающая, основная атакующая сила команды. Мощный удар из второй зоны и с задней линии, силовая подача в прыжке. Мастер спорта, выступала в высшей лиге «Б».', false, 'participant_5.jpg', 'video_2.mp4', '2002-05-30', 'Диагональная', 184, 'МС', 'Москва'),
(6, 'Тихонова Валерия Денисовна', 'Молодая доигровщица, первый сезон в студенческом волейболе. Надёжный приём, техничный удар с обводкой блока, работает над подачей в прыжке.', false, 'participant_6.jpg', 'video_3.mp4', '2006-02-17', 'Доигровщица', 178, '2 разряд', 'Дудинка'),
(7, 'Орлова Ксения Максимовна', 'Центральная блокирующая, сильна в одиночном блоке и в атаке с короткой передачи. Хорошо перемещается вдоль сетки и закрывает направление удара соперника.', false, 'participant_7.jpg', 'video_1.mp4', '2003-09-05', 'Центральная блокирующая', 186, '1 разряд', 'Норильск'),
(8, 'Иванова Софья Павловна', 'Связующая, делает ставку на быструю игру и передачи во вторую линию. Хорошая подача и игра в защите. Запасная связующая сборной ЗГУ.', false, 'participant_8.jpg', 'video_2.mp4', '2005-06-21', 'Связующая', 172, '2 разряд', 'Талнах'),
(9, 'Шарипова Амина Руслановна', 'Либеро с отличным приёмом силовой подачи. Уверенно играет в защите на задней линии, организует подстраховку и командует расстановкой при приёме.', false, 'participant_9.jpg', 'video_3.mp4', '2004-08-12', 'Либеро', 163, '1 разряд', 'Кайеркан'),
(10, 'Федорова Мария Алексеевна', 'Опытная диагональная нападающая. Атакует из второй зоны и пайпом с задней линии, сильная подача в прыжке. Играет за команду ветеранов ЗГУ.', false, 'participant_10.jpg', 'video_1.mp4', '2001-12-03', 'Диагональная', 183, 'КМС', 'Норильск');
